export type TerminalSessionInfo = {
	sessionId: string,
	workspaceKey: string,
	cwd: string,
	hasActiveForegroundChild: boolean,
	outputPaused: boolean,
	state: TerminalLifecycleState,
};

/**  Arguments for spawning a workspace-scoped terminal session (`C4.2`). */
export type TerminalSpawnArgs = {
	workspaceKey: string,
	cwd: string,
	cols: number,
	rows: number,
	shell: string | null,
};

/**  Arguments for toggling terminal visibility / fold-keepalive (`C4.2`, `C8.7`). */
export type TerminalVisibilityArgs = {
	sessionId: string,
	visible: boolean,
};

/**  Arguments for writing base64-encoded input bytes into a terminal session (`C4.2`). */
export type TerminalWriteArgs = {
	sessionId: string,
	dataBase64: string,
};

/**  Complete persisted UI state (`C6.3`). */
export type UiState = {
	windows: WindowsUiState,
	tabs: TabsUiState,
	leftSidebar?: LeftSidebarUiState,
	terminalPanel?: TerminalPanelUiState,
	filters: FiltersUiState,
	selectedWorkspaceKey: string | null,
	lastActiveDoc: LastActiveDocState | null,
	workspaceModes: { [key in string]: CaptureMode },
	hotkey: HotkeyStatus,
	backupPaths?: BackupPathsUiState,
};

/**  Arguments for `ui_state_set` (`C4.2`). */
export type UiStateArgs = {
	key: UiStatePatchKey,
	value: unknown,
};

/**  Whitelisted patch keys accepted by `ui_state_set` (`C4.2`, `C6.3`). */
export type UiStatePatchKey = "windows" | "tabs" | "leftSidebar" | "terminalPanel" | "filters" | "selectedWorkspace" | "hotkey" | "lastActiveDoc" | "workspaceModes" | "backupPaths";

/**  Result returned by `note_undo_last_append` (`C8.3`). */
export type UndoAppendResult = {
	relPath: string,
	restoredBodyHash: string,
	mtimeMs: number,
};

/**  Main window presentation mode (`C3.4`, `C6.2`). */
export type WindowMode = "standard" | "fullscreen" | "auxiliary";

/**  Window visibility and mode state pushed via `window:state` and window IPC commands (`C3.4`, `C4.3`). */
export type WindowState = {
	windowId: string,
	visible: boolean,
	fullscreen: boolean,
	mode: WindowMode | null,
	reason: HideReason | null,
};

/**  Windows section of `ui-state.json` (`C6.3`). */
export type WindowsUiState = {
	main: MainWindowState,
};

/**
 *  Legacy global workspace configuration entry (`C3.4`, `C6.2`).
 * 
 *  Deprecated in v5 refactor: directory-bound `.quicknote.yaml` replaces global workspaces.
 *  Retained for backward-compatible deserialization of existing `settings.yaml` files.
 */
export type WorkspaceConfig = {
	name: string,
	key: string,
	root: string,
	openDir: string,
	codeWorkspace: string | null,
	terminalDir: string | null,
	defaultEditor: string,
	defaultEntryDoc: string | null,
};

/**  Workspace summary for navigation (`C3.4`). */
export type WorkspaceSummary = {
	key: string,
	name: string,
	root: string,
	openDir: string,
};

/**  Arguments for `note_write` (`C3.4`). */
export type WriteNoteArgs = {
	absPath: string,
	body: string,
	baseBodyHash: string,
};

/**  Result of `note_write`; `updated_meta` only set when a missing ULID was back-filled (`D-0006`). */
export type WriteResult = {
	bodyHash: string,
	mtimeMs: number,
	updatedMeta: NoteMeta | null,
};
